('a1800000-0000-4000-8000-000000000015','a1800000-0000-4000-8000-000000000002','a1800000-0000-4000-8000-000000000003','a1800000-0000-4000-8000-000000000014',10000,4,true,true,'collective'),
('a1800000-0000-4000-8000-000000000025','a1800000-0000-4000-8000-000000000002','a1800000-0000-4000-8000-000000000003','a1800000-0000-4000-8000-000000000024',1000,1,false,false,'fixed_yield');
