('a1800000-0000-4000-8000-000000000006','a1800000-0000-4000-8000-000000000002','a1800000-0000-4000-8000-000000000003','synthetic-loan-one','a1800000-0000-4000-8000-000000000004',100000,'fixed_interest','MONTHLY_FIXED',.05,2,'2026-01-01','active','SYN-01',20000,5000,'a1800000-0000-4000-8000-000000000001'),
('a1800000-0000-4000-8000-000000000016','a1800000-0000-4000-8000-000000000002','a1800000-0000-4000-8000-000000000003','synthetic-loan-two','a1800000-0000-4000-8000-000000000004',10000,'fixed_interest','MONTHLY_FIXED',.1,1,'2026-04-01','paid','SYN-02',10000,1000,'a1800000-0000-4000-8000-000000000001');
