set local request.jwt.claim.sub='a1800000-0000-4000-8000-000000000001';
select public.create_bank_account('a1800000-0000-4000-8000-000000000003','Synthetic reconciliation unit bank','','');
select public.create_b_operation('a1800000-0000-4000-8000-000000000002','a1800000-0000-4000-8000-000000000003','synthetic-initial','legacy_opening','2026-01-01','loan_contracts','a1800000-0000-4000-8000-000000000006','{}','[{"account":"loans_receivable","amount":80000},{"account":"legacy_migration_equity","amount":-80000}]');
select public.register_savings_contribution('a1800000-0000-4000-8000-000000000025','synthetic-fixed-saving',1000,'2026-01-01',2026,1,'cash','manual');
select public.create_b_operation('a1800000-0000-4000-8000-000000000002','a1800000-0000-4000-8000-000000000003','synthetic-saving','savings_contribution_linked','2026-01-01','cycles',null,'{}','[{"account":"cash","amount":119000,"liquidity_location":"unknown"},{"account":"savings_liability","amount":-119000}]');
select public.create_b_operation('a1800000-0000-4000-8000-000000000002','a1800000-0000-4000-8000-000000000003','synthetic-fine','manual_income','2026-01-02','cycles',null,'{"category":"Multa"}','[{"account":"cash","amount":2000,"liquidity_location":"unknown"},{"account":"common_income","amount":-2000}]');
select public.create_b_operation('a1800000-0000-4000-8000-000000000002','a1800000-0000-4000-8000-000000000003','synthetic-location','liquidity_transfer','2026-10-01','cycles',null,jsonb_build_object('from_location','unknown','to_location','bank','to_bank_account_id',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank')),jsonb_build_array(jsonb_build_object('account','cash','amount',121000,'liquidity_location','bank','bank_account_id',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank')),jsonb_build_object('account','cash','amount',-121000,'liquidity_location','unknown')));
create temp table recon_before as select account,liquidity_location,bank_account_id,sum(amount) amount from ledger_entries where cycle_id='a1800000-0000-4000-8000-000000000003'group by 1,2,3;
grant select on recon_before to authenticated;
set local role authenticated;
create temp table recon_quote as select public.preview_legacy_reconciliation('a1800000-0000-4000-8000-000000000003')q;
select is((select jsonb_array_length(q->'operations')from recon_quote),5,'two interest rows, two cash rows, one fine reclassification');
select is((select(q->>'historic_interest')::numeric from recon_quote),6000::numeric,'paid interest from synthetic schedules');
select is((select(q->>'net_cash_correction')::numeric from recon_quote),74000::numeric,'net includes negative cash correction on repaid loan');
select throws_ok($$select public.confirm_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-confirm',null)$$,'P0001','La conciliacion cambio; vuelva a previsualizar.','null hash rejected');
savepoint changed;
select public.record_admin_fine('a1800000-0000-4000-8000-000000000003','synthetic-extra-fine','2026-10-17',100,'Extra',(select 'bank'),(select id from bank_accounts where display_name='Synthetic reconciliation unit bank'));
select throws_ok($$select public.confirm_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-confirm',(select q->>'preview_hash'from recon_quote))$$,'P0001','La conciliacion cambio; vuelva a previsualizar.','intervening receipt invalidates hash');
rollback to changed;
select lives_ok($$select public.confirm_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-confirm',(select q->>'preview_hash'from recon_quote))$$,'confirmation succeeds');
select is((select sum(amount)from ledger_entries where cycle_id='a1800000-0000-4000-8000-000000000003'and account='legacy_migration_equity'),0::numeric,'initial equity exactly zero');
select is((select sum(amount)from ledger_entries where cycle_id='a1800000-0000-4000-8000-000000000003'and account='loans_receivable'),80000::numeric,'principal unchanged');
select is((select count(*)from loan_payments where cycle_id='a1800000-0000-4000-8000-000000000003'),0::bigint,'no fake payments');
select is((select sum(amount)from ledger_entries where cycle_id='a1800000-0000-4000-8000-000000000003'and account='admin_payable'),(-2600)::numeric,'ten percent plus fines to administrator');
select is((select sum(amount)from ledger_entries where cycle_id='a1800000-0000-4000-8000-000000000003'and account='member_loan_profit_fund'),(-5400)::numeric,'ninety percent to members');
select is((select count(*)from public.financial_operations where cycle_id='a1800000-0000-4000-8000-000000000003'and operation_type='legacy_loan_interest_correction'),2::bigint,'one dated operation per paid interest quota');
reset role;
select is((select count(*)from public.loan_profit_shares('a1800000-0000-4000-8000-000000000003','2026-10-17')where cycle_member_id='a1800000-0000-4000-8000-000000000015'and effective_date<'2026-04-01'),0::bigint,'late member gets no interest from before joining');
select ok((select sum(amount)>0 from public.loan_profit_shares('a1800000-0000-4000-8000-000000000003','2026-10-17')where kind='ea_reserve'),'EA reserve funded chronologically');
set local role authenticated;
select is((public.preview_admin_withdrawal('a1800000-0000-4000-8000-000000000003','2026-10-17')->>'ea_reserve')::numeric,0::numeric,'fund now covers projected EA');
select ok((public.preview_admin_withdrawal('a1800000-0000-4000-8000-000000000003','2026-10-17')->>'available')::numeric>0,'administrator no longer blocked by missing history');
select lives_ok($$select public.confirm_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-confirm',(select q->>'preview_hash'from recon_quote))$$,'exact retry');
select lives_ok($$select public.confirm_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-other-key','different')$$,'different key does not apply again');
select is((select count(*)from public.legacy_reconciliations where cycle_id='a1800000-0000-4000-8000-000000000003'),1::bigint,'single reconciliation');
select throws_ok($$select public.reverse_financial_operation((select operation_ids[1]from legacy_reconciliations where cycle_id='a1800000-0000-4000-8000-000000000003'),'synthetic-split','2026-10-17','Split')$$,'P0001','Use el reverso completo de la conciliacion.','generic partial undo blocked');
savepoint undo_group;
select lives_ok($$select public.reverse_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-undo','Owner correction')$$,'atomic group undo');
select is((select sum(abs(coalesce(a.amount,0)-coalesce(b.amount,0)))from(select account,liquidity_location,bank_account_id,sum(amount)amount from ledger_entries where cycle_id='a1800000-0000-4000-8000-000000000003'group by 1,2,3)a full join recon_before b on a.account=b.account and a.liquidity_location=b.liquidity_location and a.bank_account_id is not distinct from b.bank_account_id),0::numeric,'all balances and locations return exactly');
select lives_ok($$select public.reverse_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-undo','Owner correction')$$,'undo retry idempotent');
select throws_ok($$select public.reverse_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-undo','Changed reason')$$,'P0001','La conciliacion ya fue revertida.','changed undo rejected');
rollback to undo_group;
select public.record_admin_fine('a1800000-0000-4000-8000-000000000003','synthetic-new-fine','2026-10-17',1200,'Synthetic fine','bank',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank'));
select is((select sum(amount)from ledger_entries where operation_id=(select id from financial_operations where idempotency_key='synthetic-new-fine')and account='admin_payable'),(-1200)::numeric,'new fine goes entirely to administrator');
select is((select count(*)from ledger_entries where operation_id=(select id from financial_operations where idempotency_key='synthetic-new-fine')and account='common_income'),0::bigint,'new fine does not enter common fund');
select lives_ok($$select public.record_admin_fine('a1800000-0000-4000-8000-000000000003','synthetic-new-fine','2026-10-17',1200,'Synthetic fine','bank',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank'))$$,'fine retry idempotent');
select throws_ok($$select public.record_admin_fine('a1800000-0000-4000-8000-000000000003','synthetic-new-fine','2026-10-17',1300,'Synthetic fine','bank',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank'))$$,'P0001','La clave de multa tiene otro contenido.','fine changed retry rejected');
select public.record_bank_interest_received('a1800000-0000-4000-8000-000000000003',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank'),'synthetic-interest-one','2026-02-28',90,0,0,'Synthetic');
select public.record_bank_interest_received('a1800000-0000-4000-8000-000000000003',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank'),'synthetic-interest-two','2026-05-31',60,0,0,'Synthetic');
select is((select sum(net_amount)from bank_yield_receipts where cycle_id='a1800000-0000-4000-8000-000000000003'),150::numeric,'receipts persisted once');
select is((select count(*)from bank_yield_rights where cycle_id='a1800000-0000-4000-8000-000000000003'and cycle_member_id='a1800000-0000-4000-8000-000000000025'),0::bigint,'fixed EA member excluded from bank yield');
select is((select count(*)from bank_yield_rights r join bank_yield_receipts b on b.id=r.receipt_id where r.cycle_member_id='a1800000-0000-4000-8000-000000000015'and b.effective_date<'2026-04-01'),0::bigint,'bank rights respect joining month');
create temp table before_statement as select count(*)n from financial_operations where cycle_id='a1800000-0000-4000-8000-000000000003';
select public.record_bank_statement_check('a1800000-0000-4000-8000-000000000003',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank'),'synthetic-statement','2026-10-17',1,'Unknown difference remains unassigned');
select is((select count(*)from financial_operations where cycle_id='a1800000-0000-4000-8000-000000000003'),(select n from before_statement),'statement creates no ledger operation');
select is(public.preview_bank_statement_check('a1800000-0000-4000-8000-000000000003')->>'state','recorded','comparison can be reloaded');
select public.record_bank_statement_check('a1800000-0000-4000-8000-000000000003',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank'),'synthetic-statement-new','2026-10-17',2,'Second snapshot');
select is((public.preview_bank_statement_check('a1800000-0000-4000-8000-000000000003')->'check'->>'statement_balance')::numeric,2::numeric,'last comparison wins without deleting history');
select is((select count(*)from bank_statement_checks where cycle_id='a1800000-0000-4000-8000-000000000003'),2::bigint,'both comparisons retained');
select throws_ok($$select public.record_bank_statement_check('a1800000-0000-4000-8000-000000000003',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank'),'synthetic-future','2026-10-18',2,'Future')$$,'P0001','Fecha de extracto invalida.','future statement rejected');
select is((select count(*)from(select operation_id from ledger_entries where cycle_id='a1800000-0000-4000-8000-000000000003'group by 1 having sum(amount)<>0)x),0::bigint,'every operation balances');
select is((select jsonb_array_length(public.export_natillera_backup('a1800000-0000-4000-8000-000000000002')->'tables'->'bank_statement_checks')),2,'backup includes statement history');
select is((select jsonb_array_length(public.export_natillera_backup('a1800000-0000-4000-8000-000000000002')->'tables'->'legacy_reconciliations')),1,'backup includes reconciliation provenance');
savepoint closure;
set local natillera.civil_today='2026-12-05';
select public.register_savings_contribution('a1800000-0000-4000-8000-000000000025','synthetic-final-saving',30000,'2026-12-01',2026,12,'cash','manual');
select throws_ok($$select public.confirm_member_settlement('a1800000-0000-4000-8000-000000000025','synthetic-final-early','2026-12-05',0,0,0,public.preview_member_settlement('a1800000-0000-4000-8000-000000000025','2026-12-05',0,0,0)->>'preview_hash')$$,'P0001','Primero confirme el reparto de utilidad de prestamos del cierre (financia el 12 % EA).','closing waits for loan-profit distribution');
select lives_ok($$select public.confirm_loan_profit_periods('a1800000-0000-4000-8000-000000000003','2026-12-05','synthetic-close-profit',public.preview_loan_profit_periods('a1800000-0000-4000-8000-000000000003','2026-12-05')->>'preview_hash')$$,'dated corrected interest funds December 5 distribution');
select throws_ok($$select public.confirm_member_settlement('a1800000-0000-4000-8000-000000000025','synthetic-final-early','2026-12-05',0,0,0,public.preview_member_settlement('a1800000-0000-4000-8000-000000000025','2026-12-05',0,0,0)->>'preview_hash')$$,'P0001','Primero confirme el reparto de rendimientos Pibank del cierre.','closing waits for bank-yield distribution');
select lives_ok($$select public.confirm_bank_yield_distribution('a1800000-0000-4000-8000-000000000003','2026-12-05','synthetic-close-bank',public.preview_bank_yield_distribution('a1800000-0000-4000-8000-000000000003','2026-12-05')->>'preview_hash')$$,'frozen receipts distribute at close');
select is((public.preview_member_settlement('a1800000-0000-4000-8000-000000000025','2026-12-05',0,0,0)->>'annual_admin_fee')::numeric,20000::numeric,'approved automatic administration fee applies at final settlement');
select is((public.preview_member_settlement('a1800000-0000-4000-8000-000000000025','2026-12-05',0,0,0)->>'penalty')::numeric,0::numeric,'final settlement has no early withdrawal penalty');
select lives_ok($$select public.confirm_member_settlement('a1800000-0000-4000-8000-000000000025','synthetic-final-done','2026-12-05',0,0,0,public.preview_member_settlement('a1800000-0000-4000-8000-000000000025','2026-12-05',0,0,0)->>'preview_hash')$$,'December 5 final settlement succeeds in correct order');
select throws_ok($$select public.reverse_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-dependent-undo','Too late')$$,'P0001','Hay retiros, liquidaciones o repartos dependientes.','dependent closing blocks reconciliation undo');
rollback to closure;
savepoint retroactive;
select public.register_savings_contribution('a1800000-0000-4000-8000-000000000025','synthetic-retire-saving',100000,'2026-10-17',2026,10,'cash','manual');
select is((public.preview_member_settlement('a1800000-0000-4000-8000-000000000025','2026-10-17',0,0,0)->>'penalty')::numeric,50000::numeric,'approved automatic early withdrawal penalty applies');
select public.confirm_member_settlement('a1800000-0000-4000-8000-000000000025','synthetic-early-settle','2026-10-17',0,0,0,public.preview_member_settlement('a1800000-0000-4000-8000-000000000025','2026-10-17',0,0,0)->>'preview_hash');
select public.record_bank_interest_received('a1800000-0000-4000-8000-000000000003',(select id from bank_accounts where display_name='Synthetic reconciliation unit bank'),'synthetic-pending-interest','2026-09-30',50,0,0,'Retroactive synthetic receipt');
select is((select state from bank_yield_receipts where operation_id=(select id from financial_operations where idempotency_key='synthetic-pending-interest')),'pending_review','retroactive receipt affecting a settlement remains pending');
select is((select count(*)from bank_yield_rights where receipt_id=(select id from bank_yield_receipts where operation_id=(select id from financial_operations where idempotency_key='synthetic-pending-interest'))),0::bigint,'no rights silently invented after settlement');
rollback to retroactive;
set local request.jwt.claim.sub='a1800000-0000-4000-8000-000000000099';
select is((select count(*)from bank_statement_checks where cycle_id='a1800000-0000-4000-8000-000000000003'),0::bigint,'unrelated user cannot read statement');
select throws_ok($$select public.preview_legacy_reconciliation('a1800000-0000-4000-8000-000000000003')$$,'P0001','No tiene permiso sobre este ciclo.','unrelated user cannot preview');
select throws_ok($$select public.confirm_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-forbidden','hash')$$,'P0001','No tiene permiso sobre este ciclo.','unrelated user cannot confirm');
select throws_ok($$select public.reverse_legacy_reconciliation('a1800000-0000-4000-8000-000000000003','synthetic-forbidden','No')$$,'P0001','No tiene permiso sobre este ciclo.','unrelated user cannot undo');
select ok(not has_function_privilege('anon','public.preview_legacy_reconciliation(uuid)','execute'),'anonymous preview revoked');
select ok(not has_function_privilege('anon','public.confirm_legacy_reconciliation(uuid,text,text)','execute'),'anonymous confirm revoked');
select ok(not has_function_privilege('anon','public.reverse_legacy_reconciliation(uuid,text,text)','execute'),'anonymous undo revoked');
select ok(not has_function_privilege('authenticated','public.phasea_reverse_base(uuid,text,date,text)','execute'),'internal reverse engine private');
select ok(not has_table_privilege('authenticated','public.bank_statement_checks','update'),'browser cannot modify history');
select ok(not has_table_privilege('authenticated','public.legacy_reconciliations','insert'),'browser cannot forge reconciliation');
select * from finish();
rollback;
